CREATE TABLE IF NOT EXISTS recipes (id BIGSERIAL PRIMARY KEY,slug TEXT UNIQUE NOT NULL,name TEXT NOT NULL,emoji TEXT DEFAULT '🍽️',categories TEXT[] NOT NULL DEFAULT '{}',free BOOLEAN NOT NULL DEFAULT FALSE,people TEXT,ingredients JSONB NOT NULL DEFAULT '[]'::jsonb,steps JSONB NOT NULL DEFAULT '[]'::jsonb,params JSONB NOT NULL DEFAULT '{}'::jsonb,status TEXT NOT NULL DEFAULT 'draft',update_month TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS recipe_views (id BIGSERIAL PRIMARY KEY,recipe_id BIGINT REFERENCES recipes(id) ON DELETE CASCADE,viewed_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_recipes_status_month ON recipes(status,update_month);
